{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case field")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty array")
    if not isinstance(required_symbols, list):
        raise ValueError("required_symbols must be an array")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError("required symbols must be strings")

    required = set(required_symbols)
    by_id = {}
    required_fields = ("id", "parent", "symbol", "depth", "removable", "utility")
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        if any(field not in node for field in required_fields):
            raise ValueError("node is missing a required field")

        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str) or not node_id:
            raise ValueError("node id must be a non-empty string")
        if node_id in by_id:
            raise ValueError("node ids must be unique")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be a string or null")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be a boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)):
            raise ValueError("utility must be numeric")
        if utility != utility or utility in (float("inf"), float("-inf")):
            raise ValueError("utility must be finite")

        by_id[node_id] = node

    roots = []
    children = {node_id: set() for node_id in by_id}
    for node_id, node in by_id.items():
        parent = node["parent"]
        if parent is None:
            roots.append(node_id)
            if node["depth"] != 0:
                raise ValueError("root depth must be zero")
        else:
            if parent not in by_id:
                raise ValueError("parent must reference an existing node")
            if by_id[parent]["depth"] + 1 != node["depth"]:
                raise ValueError("node depth must follow parent depth")
            children[parent].add(node_id)

    if len(roots) != 1:
        raise ValueError("nodes must form a single rooted tree")

    represented = {node["symbol"] for node in nodes}
    if not required.issubset(represented):
        raise ValueError("every required symbol must be represented")

    root_id = roots[0]
    retained = set(by_id)
    symbol_counts = {}
    for node in nodes:
        symbol = node["symbol"]
        symbol_counts[symbol] = symbol_counts.get(symbol, 0) + 1

    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))
    removed = []
    for node in candidates:
        node_id = node["id"]
        symbol = node["symbol"]
        if node_id == root_id or not node["removable"] or symbol in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue

        symbol_counts[symbol] -= 1
        if any(symbol_counts.get(required_symbol, 0) <= 0 for required_symbol in required):
            symbol_counts[symbol] += 1
            continue

        retained.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
